/**
 * SD Reboot
 */
* {
    box-sizing: border-box;
    text-align: start;
}

*::before,
*::after {
    box-sizing: inherit;
}

:focus,
select:focus,
select:active {
    outline: none;
}

html {
    font-size: 10px;
    -webkit-tap-highlight-color: rgba(0, 0, 0, 0);
}

body {
    font-family: 'Roboto', Helvetica, Arial, sans-serif;
    font-size: 1.3rem;
    line-height: 1.8rem;
}

button,
input,
optgroup,
select,
textarea {
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
    margin: 0;
    border-radius: 0;
}

input[type='search'] {
    box-sizing: border-box;
}

button {
    border: 0;
    background: transparent;
    cursor: pointer;
}

button {
    color: inherit;
}

.fade.ng-hide {
    opacity: 0;
}

.fade.ng-hide-remove,
.fade.ng-hide-add {
    display: block !important;
}

.fade.ng-hide-remove {
    transition: all linear 200ms;
}

.fade.ng-hide-add {
    position: absolute;
    transition: all linear 300ms;
}

@keyframes fadeIn {
    0% {
        opacity: 0;
    }
    50% {
        opacity: 0;
    }
    100% {
        opacity: 1;
    }
}

@keyframes dropOut2 {
    0% {
        transform: translateY(-4.8rem);
    }
    100% {
        transform: translateY(0);
    }
}

.sd-card__thumbnail {
    transition: all 0.2s ease-in;
    height: 20rem;
}

.sd-card__thumbnail.ng-hide {
    opacity: 0;
    height: 0.1rem !important;
}

@keyframes appear {
    from {
        display: none;
        opacity: 0;
    }
    to {
        display: flex;
        opacity: 1;
    }
}

@keyframes vanish {
    from {
        display: flex;
        opacity: 1;
    }
    to {
        display: none;
        opacity: 0;
    }
}

