.icn-mix {
    position: relative;
    display: inline-flex !important;
    font-size: 16px;
    height: 16px;
}
.icn-mix .icn-mix__icn {
    opacity: 0.6;
}
.icn-mix .icn-mix__sub-icn {
    position: absolute;
    font-size: 1.1rem;
    box-sizing: content-box;
    line-height: 100%;
    color: #9b27b0;
    inset-inline-end: -0.4rem;
    inset-block-end: -0.6rem;
    height: 1em;
    width: 1em;
    background-color: var(--sd-item__main-Bg) !important;
    border-radius: var(--b-radius--full);
    padding: 1px;
    z-index: 1;
    opacity: 1 !important;
}

.icn-mix--2x {
    font-size: 32px;
    height: 32px;
}
.icn-mix--2x .icn-mix__icn {
    opacity: 0.6;
    width: 32px;
    height: 32px;
    line-height: 32px;
    font-size: 32px;
}
.icn-mix--2x .icn-mix__sub-icn {
    font-size: 1.6rem;
    inset-inline-end: -0.6rem;
    inset-block-end: -0.3rem;
}

.double-size-icn {
    display: inline-block;
    height: 3.2rem;
    width: 3.2rem;
}
.double-size-icn [class^='icon-'],
.double-size-icn [class*=' icon-'] {
    width: 32px;
    height: 32px;
    line-height: 32px;
    font-size: 32px;
}

.double-size-icn--light [class^='icon-'],
.double-size-icn--light [class*=' icon-'] {
    opacity: 0.5;
}

