    /* FLOW: DOWN */
    /* FLOW: LEFT */
    /* FLOW: RIGHT */
    /* FX All The Things */
}
[sd-tooltip]:not([flow])::before,
[sd-tooltip][flow^='up']::before {
    inset-block-end: 100%;
    border-bottom-width: 0;
    border-top-color: var(--sd-colour-background__tooltip);
}
[sd-tooltip]:not([flow])::after,
[sd-tooltip][flow^='up']::after {
    inset-block-end: calc(100% + 5px);
}
[sd-tooltip]:not([flow])::before,
[sd-tooltip]:not([flow])::after,
[sd-tooltip][flow^='up']::before,
[sd-tooltip][flow^='up']::after {
    inset-inline-start: 50%;
    transform: translate(-50%, -0.5em);
}
[sd-tooltip][flow^='down']::before {
    inset-block-start: 100%;
    border-top-width: 0;
