.hamburger__box {
    width: 18px;
    height: 15px;
    display: inline-block;
    position: relative;
}

.hamburger__inner {
    display: block;
    inset-block-start: 50%;
    margin-block-start: -1.5px;
}
.hamburger__inner,
.hamburger__inner::before,
.hamburger__inner::after {
    width: 18px;
    height: 3px;
    background-color: #fff;
    border-radius: 1px;
    position: absolute;
    transition-property: transform;
    transition-duration: 0.15s;
    transition-timing-function: ease;
}
.hamburger__inner::before,
.hamburger__inner::after {
    content: '';
    display: block;
}
.hamburger__inner::before {
    inset-block-start: -6px;
}
.hamburger__inner::after {
    inset-block-end: -6px;
}

/* Spin */
.hamburger--spin .hamburger__inner {
    transition-duration: 0.22s;
    transition-timing-function: cubic-bezier(0.55, 0.055, 0.675, 0.19);
}
.hamburger--spin .hamburger__inner::before {
    transition:
        top 0.1s 0.25s ease-in,
        opacity 0.1s ease-in;
}
.hamburger--spin .hamburger__inner::after {
    transition:
        bottom 0.1s 0.25s ease-in,
        transform 0.22s cubic-bezier(0.55, 0.055, 0.675, 0.19);
}

.hamburger--spin.is-active .hamburger__inner {
    transform: rotate(225deg);
    transition-delay: 0.12s;
    transition-timing-function: cubic-bezier(0.215, 0.61, 0.355, 1);
}
.hamburger--spin.is-active .hamburger__inner::before {
    inset-block-start: 0;
    opacity: 0;
    transition:
        top 0.1s ease-out,
        opacity 0.1s 0.12s ease-out;
}
.hamburger--spin.is-active .hamburger__inner::after {
    inset-block-end: 0;
    transform: rotate(-90deg);
    transition:
        bottom 0.1s ease-out,
        transform 0.22s 0.12s cubic-bezier(0.215, 0.61, 0.355, 1);
}

/* Squeeze */
.hamburger--squeeze .hamburger__inner {
    transition-duration: 0.075s;
    transition-timing-function: cubic-bezier(0.55, 0.055, 0.675, 0.19);
}
.hamburger--squeeze .hamburger__inner::before {
    transition:
        top 0.075s 0.12s ease,
        opacity 0.075s ease;
}
.hamburger--squeeze .hamburger__inner::after {
    transition:
        bottom 0.075s 0.12s ease,
        transform 0.075s cubic-bezier(0.55, 0.055, 0.675, 0.19);
}

.hamburger--squeeze.is-active .hamburger__inner {
    transform: rotate(45deg);
    transition-delay: 0.12s;
    transition-timing-function: cubic-bezier(0.215, 0.61, 0.355, 1);
}
.hamburger--squeeze.is-active .hamburger__inner::before {
    inset-block-start: 0;
    opacity: 0;
    transition:
        top 0.075s ease,
        opacity 0.075s 0.12s ease;
}
.hamburger--squeeze.is-active .hamburger__inner::after {
    inset-block-end: 0;
