.sd-photo-preview__video {
    position: relative;
    grid-column: 1/2;
    grid-row: 1/2;
    text-align: center;
    background-color: var(--sd-colour-bg__photo-preview);
    max-height: 100%;
}
.sd-photo-preview__image.actioning::before,
.sd-photo-preview__video.actioning::before {
    content: '';
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
    inset-block-end: 0;
    inset-inline-start: 0;
    z-index: 999;
    background-image: url(three-dots.svg);
    background-repeat: no-repeat;
    background-position: center center;
    background-size: 60px;
    background-color: var(--sd-colour-overlay-actioning);
}

.sd-photo-preview__video {
    display: grid;
    grid-template-rows: 1fr auto;
    grid-template-columns: 1fr;
    align-items: center;
    justify-content: center;
    max-height: none;
    background-color: #232323;
}
.sd-photo-preview__video .sd-photo-preview__video-inner {
    grid-row: 1/2;
    display: grid;
    grid-template-rows: 1fr auto;
    grid-template-columns: 1fr;
    align-items: center;
    justify-content: center;
    margin: auto;
    height: auto;
    width: auto;
    max-width: 100%;
    min-width: 48rem;
}
.sd-photo-preview__video .sd-photo-preview__video-container {
    grid-row: 1/2;
    margin: 0;
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
}
.sd-photo-preview__video .sd-photo-preview__video-container video {
    max-width: 110vh;
    width: auto;
    height: auto;
    max-height: 100vh;
    margin-block-start: 2rem;
}
.sd-photo-preview__video .sd-photo-preview__video-tools {
    grid-row: 2/3;
    margin: 0.8rem auto 3.2rem;
    padding: 1.2rem;
    border-radius: 0.8rem;
    background-color: rgba(0, 0, 0, 0.3);
    height: 6rem;
    display: flex;
    flex-direction: row;
    align-items: center;
    width: 100%;
}
.sd-photo-preview__video .sd-photo-preview__video-tools--blank {
    background-color: rgba(0, 0, 0, 0);
    padding: 0.6rem;
}

.sd-photo-preview__label {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    background: rgba(0, 0, 0, 0.25);
    color: inherit;
    padding: 0.8rem 2rem;
    margin: 1rem auto;
    line-height: 100%;
    border-radius: var(--b-radius--x-small);
    font-weight: 300;
    min-width: 16rem;
}

.sd-photo-preview__image {
    max-height: calc(100vh - 53px);
    max-width: calc(100vw - 40rem);
    transition: max-width 0.2s ease-in-out;
    padding: 1.6rem;
}
.sd-photo-preview__image img {
    max-width: 100%;
    max-height: 100%;
    height: auto;
    margin: auto;
}

.sd-column-box__main-column.sd-column-box__main-column--expanded .sd-photo-preview__image {
    max-width: 100vw;
}

.sd-photo-preview__thumb-strip {
    grid-column: 1/2;
    grid-row: 2/3;
    min-height: 16rem;
    background-color: rgba(0, 0, 0, 0.2);
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.2);
    position: relative;
    overflow-y: auto;
}

.sd-photo-preview__thumb-strip--video {
    min-height: 10rem;
    display: flex;
    flex-direction: row;
    overflow: visible;
}

.sd-photo-preview__thumbnail-edit {
    position: relative;
    height: 16rem;
    flex-grow: 0;
}
.sd-photo-preview__thumbnail-edit img {
    max-width: 100%;
    height: auto;
    max-height: 16rem;
    display: block;
}
.sd-photo-preview__thumbnail-edit .sd-photo-preview__thumbnail-edit-label {
    position: absolute;
    inset-block-start: -2.2rem;
    inset-inline-start: 0;
    inset-inline-end: 0;
    height: 2rem;
    text-align: center;
    opacity: 0.5;
}

.image-overlay {
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
    inset-block-end: 0;
    inset-inline-start: 0;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    background-color: rgba(0, 0, 0, 0.5);
    transition: 0.2s linear opacity;
    z-index: 1;
    opacity: 0;
    color: white;
}
.image-overlay:hover {
    opacity: 1;
}

.image-overlay__button-block {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: center;
    flex-grow: 1;
}

.image-overlay__button {
    flex-grow: 0;
    flex-shrink: 0;
    color: #fff;
    width: 4.8rem;
    height: 4.8rem;
    border: 2px solid rgba(255, 255, 255, 0.6);
    border-radius: var(--b-radius--full);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    transition: 0.2s linear all;
    cursor: pointer;
    text-decoration: none;
    background-color: rgba(0, 0, 0, 0.2);
}
.image-overlay__button i {
    color: inherit;
    line-height: 1;
    opacity: 0.6;
    transition: 0.2s linear all;
}
.image-overlay__button:hover {
    border-color: white;
    background-color: rgba(0, 0, 0, 0.6);
    text-decoration: none;
}
.image-overlay__button:hover i {
    opacity: 1;
}
.image-overlay__button:active {
    border-color: var(--sd-colour-interactive);
    background-color: rgba(0, 0, 0, 0.8);
}
.image-overlay__button:active i {
    color: var(--sd-colour-interactive);
}

.image-overlay__button + .image-overlay__button {
    margin-inline-start: 0.8rem;
}

.sd-photo-preview__video-frames {
    position: relative;
    flex-grow: 1;
}

.sd-photo-preview--view-video .sd-photo-preview__video .sd-photo-preview__video-inner {
    max-height: calc(100vh - 53px);
}

.sd-photo-preview--edit-video .sd-photo-preview__video .sd-photo-preview__video-inner {
    max-height: calc(100vh - 53px - 160px);
    max-width: 100vw;
}
.sd-photo-preview--edit-video
    .sd-photo-preview__video
    .sd-photo-preview__video-inner
    .sd-photo-preview__video-container
    video {
    max-width: calc(100vw - 4rem);
    max-height: calc(100vh - 53px - 160px - 100px);
}

.sd-photo-preview--view-video .sd-photo-preview__video .sd-photo-preview__video-inner {
    max-height: calc(100vh - 53px);
    max-width: calc(100vw - 44rem);
}
.sd-photo-preview--view-video
    .sd-photo-preview__video
    .sd-photo-preview__video-inner
    .sd-photo-preview__video-container
    video {
    max-width: calc(100vw - 44rem);
    max-height: calc(100vh - 53px - 90px);
}

.sd-photo-preview__slide-in-button {
    position: absolute !important;
    inset-block-start: 2.4rem;
    inset-inline-end: 0;
    z-index: 2;
    background-color: rgba(255, 255, 255, 0.1);
    height: 4.8rem;
    width: 4.8rem;
    color: white;
    display: flex;
    flex-direction: row;
    align-items: center;
    padding: 0 0 0 1.6rem;
    border-radius: 6px 0 0 6px;
    opacity: 0.5;
    cursor: pointer;
    text-decoration: none !important;
    transition: all 0.2s ease-out;
}
.sd-photo-preview__slide-in-button [class^='icon-'],
.sd-photo-preview__slide-in-button [class*=' icon-'] {
    color: white;
    flex-shrink: 0;
}
.sd-photo-preview__slide-in-button:hover {
    opacity: 1;
}
.sd-photo-preview__slide-in-button:active {
    background-color: var(--sd-colour-interactive);
    opacity: 1;
}

.sd-photo-preview__nav-button {
    border-radius: var(--b-radius--full);
    cursor: pointer;
    height: 5.6rem;
    line-height: 5.6rem;
    position: absolute;
    inset-block-start: calc(50% - 2.8rem);
    width: 5.6rem;
    box-shadow:
        0 4px 24px rgba(0, 0, 0, 0.2),
        0 10px 28px rgba(0, 0, 0, 0.35);
    color: white;
    transition: all 0.2s ease-out;
    background-color: rgba(0, 0, 0, 0.8);
    opacity: 0.3;
}
.sd-photo-preview__nav-button:hover {
    opacity: 0.6;
    background-color: rgba(0, 0, 0, 0.9);
}
.sd-photo-preview__nav-button:active {
    opacity: 0.8;
    background-color: var(--sd-colour-interactive);
}
.sd-photo-preview__nav-button::after {
    content: ' ';
    font-family: 'sd_icons';
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: 0;
    text-align: center;
    z-index: 2;
    color: white;
    width: 5.6rem;
    font-size: 3.2rem;
}

.sd-photo-preview__nav-button--next {
    inset-inline-end: 0.8rem;
    color: inherit;
}
.sd-photo-preview__nav-button--next::after {
    content: '\e643';
}

.sd-photo-preview__nav-button--prev {
    inset-inline-start: 0.8rem;
    color: inherit;
}
.sd-photo-preview__nav-button--prev::after {
    content: '\e642';
}

.upload__target {
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
    inset-block-end: 0;
    inset-inline-start: 0;
    z-index: 0;
    border: 2px dashed var(--sd-colour-interactive);
    background-color: var(--sd-colour-interactive--alpha-10);
}

.upload__info {
    margin: 0 auto;
    max-width: 40rem;
    position: relative;
    inset-block-start: 50%;
    margin-block-start: -10.6rem;
    z-index: 1;
}

.upload__info-icon {
    margin: 0 auto;
    height: 7.4rem;
    width: 9rem;
    background-image: url(icon_image_stack--white.svg);
    opacity: 0.25;
    text-align: center;
}

.upload__info-heading {
    margin: 0 auto;
    opacity: 0.5;
    text-align: center;
    padding-block-start: 3rem;
    text-align: center;
    color: var(--color-text-light);
    font-size: 2.4rem;
    font-weight: 300;
}

.upload__info-label {
    position: relative;
    text-align: center;
    font-style: italic;
    margin: 2.2rem auto;
    color: var(--color-text-lighter);
    opacity: 0.85;
}
.upload__info-label::after,
.upload__info-label::before {
    content: '___________';
    position: absolute;
    inset-block-start: -0.5rem;
    color: inherit;
    opacity: 0.25;
}
.upload__info-label::after {
    margin-inline-start: 1.5rem;
}
.upload__info-label::before {
    margin-inline-start: -7.8rem;
}

.upload__info-button {
    display: block;
    margin: 0 auto;
    text-align: center;
    opacity: 0.75;
}

.sd-photo-preview__thumb-strip:hover .upload-target {
    display: block;
}

.sd-media-carousel {
    position: relative;
    align-items: center;
    flex-direction: row;
    display: flex;
}

.sd-media-carousel__dialog {
    display: flex;
    max-height: 100%;
    flex: 0 1 auto;
    flex-direction: column;
    margin: 0 auto;
    max-width: 900px;
    width: 100%;
    position: relative;
}

.sd-media-carousel__content {
    background-clip: padding-box;
    outline: 0;
    box-shadow:
        0 1px 4px rgba(0, 0, 0, 0.25),
        0 0 1px 1px rgba(0, 0, 0, 0.12);
    display: flex;
    flex-direction: column;
    flex: 0 0 100%;
    position: relative;
}

.sd-media-carousel__page {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    position: relative;
    flex-grow: 0;
    flex-shrink: 0;
    align-items: center;
    width: 100%;
    position: relative;
    overflow: hidden;
    text-align: center;
}
.sd-media-carousel__page img,
.sd-media-carousel__page video {
    max-height: 40em;
    width: auto !important;
    margin: 0 auto !important;
}

.sd-media-carousel__page-media {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    position: relative;
    flex-grow: 0;
    flex-shrink: 0;
    align-items: center;
    background-color: rgba(0, 0, 0, 0.12);
    color: #fff;
    width: 100%;
    position: relative;
    overflow: hidden;
    text-align: center;
}
.sd-media-carousel__page-media img {
    max-width: 100%;
    max-height: 100%;
    height: auto;
    margin: auto;
}

.sd-media-carousel__nav-button {
    border-radius: var(--b-radius--full);
    cursor: pointer;
    height: 3.6rem;
    line-height: 3.6rem;
    position: absolute;
    inset-block-start: calc(50% - 6.5rem);
    width: 3.6rem;
    box-shadow:
        0 0 6px rgba(0, 0, 0, 0.25),
        0 0 1px 1px rgba(0, 0, 0, 0.12);
    color: var(--color-text);
    transition:
        all 0.2s ease-out,
        color 0.1s ease-out;
    background-color: rgba(255, 255, 255, 0.3);
    z-index: 3;
    transition: opacity 0.2s ease-out;
    opacity: 0;
}
.sd-media-carousel__nav-button:hover {
    background-color: rgba(255, 255, 255, 0.65);
}
.sd-media-carousel__nav-button:active {
    background-color: white;
}
.sd-media-carousel__nav-button::after {
    content: ' ';
    font-family: 'sd_icons';
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    position: absolute;
    inset-block-start: 0;
    text-align: center;
    z-index: 2;
    color: inherit;
    width: 3.6rem;
    font-size: 2.4rem;
}

.sd-media-carousel__nav-button--next {
    inset-inline-end: -18px;
    color: inherit;
}
.sd-media-carousel__nav-button--next::after {
    content: '\e643';
}

.sd-media-carousel__nav-button--prev {
    inset-inline-start: -18px;
    color: inherit;
}
.sd-media-carousel__nav-button--prev::after {
    content: '\e642';
}

.sd-media-carousel__nav-button--next-inner {
    inset-inline-end: 0;
    color: var(--color-text);
    border-radius: var(--b-radius--full) 0 0 var(--b-radius--full);
    box-shadow: none;
}
.sd-media-carousel__nav-button--next-inner::after {
    content: '\e643';
}

.sd-media-carousel__nav-button--prev-inner {
    inset-inline-start: 0;
    color: var(--color-text);
    border-radius: 0 var(--b-radius--full) var(--b-radius--full) 0;
    box-shadow: none;
}
.sd-media-carousel__nav-button--prev-inner::after {
    content: '\e642';
}

.sd-media-carousel__nav-button--next-inner::after,
.sd-media-carousel__nav-button--prev-inner::after {
    opacity: 0.5;
    transition: opacity 0.2s ease-out;
}

.sd-media-carousel__nav-button--next-inner:hover::after,
.sd-media-carousel__nav-button--prev-inner:hover::after {
    opacity: 1;
    color: var(--color-text);
}

.sd-media-carousel__nav-button--next-inner:active::after,
.sd-media-carousel__nav-button--prev-inner:active::after {
    color: var(--sd-colour-interactive);
}

.sd-media-carousel__nav-button--disabled {
    background-color: rgba(255, 255, 255, 0.4) !important;
    cursor: default;
    opacity: 0.2;
}
.sd-media-carousel__nav-button--disabled::after {
    opacity: 0.75;
    color: var(--color-text) !important;
}

.sd-media-carousel__dialog:hover .sd-media-carousel__nav-button {
    opacity: 1;
}

.sd-media-carousel__page-indication-bar {
    inset-block-end: -3.6rem;
    height: 2.6rem;
    position: absolute;
    text-align: center;
    width: 100%;
}

.sd-media-carousel__page-indicator {
    background-color: rgba(255, 255, 255, 0.2);
    border: 1px solid rgba(0, 0, 0, 0.4);
    border-radius: var(--b-radius--full);
    cursor: pointer;
    display: inline-block;
    height: 1.4rem;
    width: 1.4rem;
    margin: 0.6rem;
    transition:
        all 0.2s ease-out,
        color 0.1s ease-out;
}

.sd-media-carousel__page-indicator--selected {
    background-color: rgba(255, 255, 255, 0.8);
    border-color: rgba(0, 0, 0, 0.6);
}

.sd-media-carousel__thumb-strip {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(9rem, 1fr));
    grid-gap: 1rem;
    margin: 1.4rem 0;
}
.sd-media-carousel__thumb-strip i {
    margin: auto;
    color: inherit;
}

.sd-media-carousel__thumb-strip-item {
    box-shadow:
        0 1px 4px rgba(0, 0, 0, 0.25),
        0 0 1px 1px rgba(0, 0, 0, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.2);
    background-color: inherit;
    display: flex;
    flex-direction: column;
    cursor: pointer;
    transition: all ease-in 0.2s;
}
.sd-media-carousel__thumb-strip-item:hover {
    box-shadow:
        0 1px 4px rgba(0, 0, 0, 0.35),
        0 0 1px 1px rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(255, 255, 255, 0.4);
}

.sd-media-carousel__thumb-strip-item--active {
    outline: 1px solid var(--sd-colour-interactive);
    border: 1px solid rgba(255, 255, 255, 0.8);
    box-shadow:
        0 1px 4px rgba(0, 0, 0, 0.35),
        0 0 1px 1px rgba(0, 0, 0, 0.4);
    cursor: default;
}
.sd-media-carousel__thumb-strip-item--active .sd-media-carousel__thumb img {
    filter: brightness(1) grayscale(100%);
}

.sd-media-carousel__thumb {
    display: flex;
    flex-grow: 0;
    flex-shrink: 0;
    flex-direction: column;
    align-items: center;
    height: 6rem;
    padding: 0;
    width: 100%;
    position: relative;
    overflow: hidden;
    text-align: center;
    background-color: #2b2b2b;
}
.sd-media-carousel__thumb img {
    max-width: 100%;
    max-height: 6rem;
    object-fit: cover;
    object-position: 50% 50%;
}
.sd-media-carousel__thumb i {
    font-size: 3.2rem;
    line-height: 3.2rem;
    width: 3.2rem;
    height: 3.2rem;
    margin: auto;
    color: white;
    opacity: 0.35;
}

.sd-media-carousel__thumb--add {
    box-shadow:
        0 1px 4px rgba(0, 0, 0, 0.25),
        0 0 1px 1px rgba(0, 0, 0, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.8);
    display: flex;
    flex-direction: column;
    cursor: pointer;
    transition: all ease-in 0.2s;
}
.sd-media-carousel__thumb--add:hover {
    box-shadow:
        0 1px 4px rgba(0, 0, 0, 0.35),
        0 0 1px 1px rgba(0, 0, 0, 0.4);
    border: 1px solid white;
}

.sd-media-carousel__media-caption,
.sd-media-carousel__media-title {
    color: inherit;
    position: relative;
    padding: 1.2rem;
    width: 100%;
    font-size: 1.4rem;
    text-align: start;
    font-weight: 300;
    line-height: 140%;
    border: 1px solid transparent;
    transition: all ease-in-out 0.2s;
    background-color: transparent;
}
.sd-media-carousel__media-caption[contenteditable='true']:hover,
.sd-media-carousel__media-captiontextarea:not(disabled):hover,
.sd-media-carousel__media-title[contenteditable='true']:hover,
.sd-media-carousel__media-titletextarea:not(disabled):hover {
    border-color: var(--sd-colour-interactive--alpha-60);
}
.sd-media-carousel__media-caption[contenteditable='true']:focus,
.sd-media-carousel__media-captiontextarea:not(disabled):focus,
.sd-media-carousel__media-title[contenteditable='true']:focus,
.sd-media-carousel__media-titletextarea:not(disabled):focus {
    border-color: var(--sd-colour-interactive);
    box-shadow: inset 0 -1px 0 0 var(--sd-colour-interactive);
}
.sd-media-carousel__media-caption[contenteditable='true']:empty:before,
.sd-media-carousel__media-captiontextarea:not(disabled):empty:before,
.sd-media-carousel__media-title[contenteditable='true']:empty:before,
.sd-media-carousel__media-titletextarea:not(disabled):empty:before {
    position: absolute;
    content: attr(sd-placeholder) ' ';
    opacity: 0.55;
    color: inherit;
    font-weight: 300;
    cursor: text;
}

textarea.sd-media-carousel__media-caption,
textarea.sd-media-carousel__media-title {
    color: inherit;
    position: relative;
    padding: 1.2rem;
    width: 100%;
    font-size: 1.4rem;
    text-align: start;
    font-weight: 300;
    line-height: 140%;
    border: 1px solid transparent;
    transition: all ease-in-out 0.2s;
    background-color: transparent;
}
textarea.sd-media-carousel__media-caption:not(disabled):hover,
textarea.sd-media-carousel__media-title:not(disabled):hover {
    border-color: var(--sd-colour-interactive--alpha-60);
}
textarea.sd-media-carousel__media-caption:not(disabled):focus,
textarea.sd-media-carousel__media-title:not(disabled):focus {
    border-color: var(--sd-colour-interactive);
    box-shadow: inset 0 0 0 4px var(--sd-colour-interactive--alpha-30);
}
textarea.sd-media-carousel__media-caption:not(disabled):empty:before,
textarea.sd-media-carousel__media-title:not(disabled):empty:before {
    position: absolute;
    content: attr(sd-placeholder) ' ';
    opacity: 0.55;
    color: inherit;
    font-weight: 300;
    cursor: text;
}

.sd-media-carousel__media-caption {
    min-height: 4rem;
}

.sd-media-carousel__media-title {
    font-size: 1.5rem;
    font-weight: 500;
}

.sd-editor--theme-blue .sd-media-carousel__content,
.sd-editor--theme-dark .sd-media-carousel__content {
    outline: 1px solid rgba(255, 255, 255, 0.2);
}

.editor-popup {
    display: none;
    position: fixed;
}

.editor-popup--open {
    display: inline-block;
    z-index: 1040;
}

.editor-popup--annotation {
    border-block-start: 3px solid #a2df58;
}

.editor-popup--comment {
    border-block-start: 3px solid #fff170;
}

.editor-popup__main {
    display: flex;
    color: var(--color-text);
    width: 32rem;
    max-height: 100%;
}
.editor-popup__main.editor-popup__main--floating {
