.sd-slider__range,
input[type='range'] {
    width: 100%;
    position: relative;
    height: 0.2rem;
    margin-block-start: 1.25rem;
    margin-block-end: 1.25rem;
    background-color: rgba(123, 123, 123, 0.5);
    cursor: pointer;
    user-select: none;
    touch-action: none;
    border: 0;
    padding: 0;
    min-height: 0;
    -webkit-appearance: none;
}
.sd-slider__range::-webkit-slider-thumb,
input[type='range']::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 1.6rem;
    height: 1.6rem;
    transform: scale(1);
    border-radius: var(--b-radius--full);
    background-color: var(--sd-colour-interactive);
    transition:
        transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        background-color 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        opacity 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
    touch-action: manipulation;
    cursor: pointer;
    cursor: -webkit-grab;
    cursor: grab;
}
.sd-slider__range::-webkit-slider-thumb:hover,
input[type='range']::-webkit-slider-thumb:hover {
    background-color: var(--sd-colour-interactive--darken-10);
}
.sd-slider__range::-webkit-slider-thumb:active,
input[type='range']::-webkit-slider-thumb:active {
    transform: scale(1.4);
    cursor: -webkit-grabbing;
    cursor: grabbing;
}
.sd-slider__range:focus,
input[type='range']:focus {
    box-shadow: 0 0 0 1px rgba(123, 123, 123, 0.3);
}
.sd-slider__range:focus::-webkit-slider-thumb,
input[type='range']:focus::-webkit-slider-thumb {
    background-color: var(--sd-colour-interactive--darken-10);
}

.sd-slider {
    position: relative;
    height: 0.2rem;
    margin-block-start: 1.25rem;
    margin-block-end: 2.25rem;
    background-color: rgba(123, 123, 123, 0.5);
    cursor: pointer;
    user-select: none;
    touch-action: none;
    -webkit-appearance: none;
}

.sd-slider__handle {
    position: absolute;
    inset-block-start: -0.7rem;
    inset-inline-start: 0;
    z-index: 1;
    display: inline-block;
    width: 1.6rem;
    height: 1.6rem;
    transform: scale(1);
    border-radius: var(--b-radius--full);
    background-color: var(--sd-colour-interactive);
    transition:
        transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        background-color 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        opacity 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
    touch-action: manipulation;
    cursor: pointer;
    cursor: -webkit-grab;
    cursor: grab;
}
.sd-slider__handle:hover {
    background-color: var(--sd-colour-interactive--darken-10);
}

.sd-slider__handle:active,
.sd-slider__handle--active {
    transform: scale(1.4);
    cursor: -webkit-grabbing;
    cursor: grabbing;
}

.sd-slider__focus-ring {
    position: absolute;
    inset-block-start: -1.4rem;
    inset-inline-start: 0;
    z-index: 0;
    margin-inline-start: -0.7rem;
    display: inline-block;
    width: 3rem;
    height: 3rem;
    transform: scale(0);
    border-radius: var(--b-radius--full);
    background-color: var(--sd-colour-interactive--alpha-30);
    opacity: 0;
    transition:
        transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        background-color 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        opacity 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
}
.sd-slider__focus-ring:focus {
    transform: scale(1);
    opacity: 1;
    background-color: var(--sd-colour-interactive--darken-10);
}

.sd-slider__fill {
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: 0;
    display: inline-block;
    max-width: 100%;
    height: 0.2rem;
    background-color: var(--sd-colour-interactive);
    transition:
        transform 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        background-color 0.4s cubic-bezier(0.25, 0.8, 0.25, 1),
        opacity 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);
}

.sd-loader--inline,
.sd-loader {
    display: inline-flex;
    width: 100%;
    min-width: 90px;
    height: 100%;
    min-height: 30px;
