.icn-mix {
    position: relative;
    display: inline-flex !important;
    font-size: 16px;
    height: 16px;
}
.icn-mix .icn-mix__icn {
    opacity: 0.6;
}
.icn-mix .icn-mix__sub-icn {
    position: absolute;
    font-size: 1.1rem;
    box-sizing: content-box;
    line-height: 100%;
    color: #9b27b0;
    inset-inline-end: -0.4rem;
    inset-block-end: -0.6rem;
    height: 1em;
    width: 1em;
    background-color: var(--sd-item__main-Bg) !important;
    border-radius: var(--b-radius--full);
    padding: 1px;
    z-index: 1;
    opacity: 1 !important;
}

.icn-mix--2x {
    font-size: 32px;
    height: 32px;
}
.icn-mix--2x .icn-mix__icn {
    opacity: 0.6;
    width: 32px;
    height: 32px;
    line-height: 32px;
    font-size: 32px;
}
.icn-mix--2x .icn-mix__sub-icn {
    font-size: 1.6rem;
    inset-inline-end: -0.6rem;
    inset-block-end: -0.3rem;
}

.double-size-icn {
    display: inline-block;
    height: 3.2rem;
    width: 3.2rem;
}
.double-size-icn [class^='icon-'],
.double-size-icn [class*=' icon-'] {
    width: 32px;
    height: 32px;
    line-height: 32px;
    font-size: 32px;
}

.double-size-icn--light [class^='icon-'],
.double-size-icn--light [class*=' icon-'] {
    opacity: 0.5;
}

.subnav .icn-mix__sub-icn {
    background-color: var(--sd-colour-panel-bg--100) !important;
}

.subnav--darker .icn-mix__sub-icn {
    background-color: var(--sd-colour-panel-bg--200) !important;
}

.subnav--dark-blue-grey .icn-mix__sub-icn {
    background-color: var(--color-subnav-bg--blueGrey-10) !important;
    color: #d686e4;
}

.subnav--dark-blue-grey .icn-mix__icn {
    color: inherit;
    opacity: 1;
}

.side-panel__top-tools .icn-mix__sub-icn {
    background-color: #f0f0f0;
}

.side-panel__top-tools--dark-blue-grey .icn-mix__sub-icn {
    background-color: var(--color-subnav-bg--blueGrey-10);
    color: #d686e4;
}

.side-panel__top-tools--dark-blue-grey .icn-mix__icn {
    color: inherit;
    opacity: 1;
}

.p-disabled {
    opacity: 0.5;
}

.p-autocomplete {
    display: contents;
}

.p-inputwrapper {
    position: relative;
}

.p-autocomplete-panel {
    background-color: var(--color-dropdown-menu-Bg);
    color: var(--color-dropdown-menu-text);
    box-shadow: var(--sd-shadow__dropdown);
    border-radius: var(--b-radius--small);
    margin-block-start: 16px;
    padding: 1rem 0;
}
.p-autocomplete-panel .p-autocomplete-items {
    padding: 0;
}
.p-autocomplete-panel .p-autocomplete-list-item,
.p-autocomplete-panel .p-autocomplete-item {
    display: block;
    font-weight: normal;
    line-height: 1.2;
    min-height: 3rem;
    white-space: nowrap;
    color: inherit;
    background-color: transparent;
    padding-block-start: 0.6rem;
    padding-block-end: 0.6rem;
    padding-inline-start: 1.6rem;
    padding-inline-end: 1.6rem;
    margin-block-end: 0.2rem;
    font-size: 1.3rem;
    text-decoration: none;
    text-align: start;
    transition: background-color ease 0.1s;
}
.p-autocomplete-panel .p-autocomplete-list-item:hover,
.p-autocomplete-panel .p-autocomplete-list-item:focus,
.p-autocomplete-panel .p-autocomplete-list-item.p-highlight,
.p-autocomplete-panel .p-autocomplete-item:hover,
.p-autocomplete-panel .p-autocomplete-item:focus,
.p-autocomplete-panel .p-autocomplete-item.p-highlight {
    background-color: var(--sd-colour-interactive--alpha-20);
    text-decoration: none;
    cursor: pointer;
